const searchCompendium = `-- name: SearchCompendium :many
SELECT e.id, e.kind, e.slug, e.name, e.source_key, e.is_homebrew,
    CAST(COALESCE((SELECT group_concat(c.value, ' ') FROM json_each(e.data_json, '$.classes') AS c), json_extract(e.data_json, '$.subclass_of'), '') AS TEXT) AS classes,
    CAST(COALESCE(json_extract(e.data_json, '$.category'), '') AS TEXT) AS category,
    CAST(COALESCE(json_extract(e.data_json, '$.size'), '') AS TEXT) AS size,
    CAST(COALESCE(json_extract(e.data_json, '$.alignment'), '') AS TEXT) AS alignment
FROM compendium_fts
JOIN compendium_entries AS e ON e.id = compendium_fts.rowid
WHERE compendium_fts MATCH CAST(?1 AS TEXT)
  AND (CAST(?2 AS TEXT) = '' OR instr(',' || CAST(?2 AS TEXT) || ',', ',' || e.kind || ',') > 0)
  AND (CAST(?3 AS TEXT) = '' OR EXISTS (SELECT 1 FROM monster_habitats AS h WHERE h.entry_id = e.id AND instr(',' || CAST(?3 AS TEXT) || ',', ',' || h.habitat || ',') > 0))
  AND (e.scoped = 0 OR CAST(?4 AS INTEGER) = 0
       OR EXISTS (SELECT 1 FROM compendium_campaigns AS l WHERE l.entry_id = e.id AND l.campaign_id = CAST(?4 AS INTEGER)))
ORDER BY compendium_fts.rank
LIMIT ?5
`

type SearchCompendiumParams struct {
	Query      string
	Kind       string
	Habitat    string
	CampaignID int64
	MaxResults int64
}

type SearchCompendiumRow struct {
	ID         int64
	Kind       string
	Slug       string
	Name       string
	SourceKey  string
	IsHomebrew bool
	Classes    string
	Category   string
	Size       string
	Alignment  string
}

func (q *Queries) SearchCompendium(ctx context.Context, arg SearchCompendiumParams) ([]SearchCompendiumRow, error) {
	rows, err := q.db.QueryContext(ctx, searchCompendium,
		arg.Query,
		arg.Kind,
		arg.Habitat,
		arg.CampaignID,
		arg.MaxResults,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchCompendiumRow{}
	for rows.Next() {
		var i SearchCompendiumRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Slug,
			&i.Name,
			&i.SourceKey,
			&i.IsHomebrew,
			&i.Classes,
			&i.Category,
			&i.Size,
			&i.Alignment,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

