const upsertCompendiumEntry = `-- name: UpsertCompendiumEntry :exec
INSERT INTO compendium_entries (
    kind, slug, name, source_key, data_json, body_text, is_homebrew, content_hash
) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (kind, slug, source_key) DO UPDATE
SET name = excluded.name, data_json = excluded.data_json,
    body_text = excluded.body_text, content_hash = excluded.content_hash,
    imported_at = CURRENT_TIMESTAMP
WHERE compendium_entries.content_hash <> excluded.content_hash
`

type UpsertCompendiumEntryParams struct {
	Kind        string
	Slug        string
	Name        string
	SourceKey   string
	DataJson    string
	BodyText    string
	IsHomebrew  bool
	ContentHash string
}

// UpsertCompendiumEntry keeps the row id across re-imports so combatants and
// entities that reference it stay linked. Unchanged content is not rewritten.
func (q *Queries) UpsertCompendiumEntry(ctx context.Context, arg UpsertCompendiumEntryParams) error {
	_, err := q.db.ExecContext(ctx, upsertCompendiumEntry,
		arg.Kind,
		arg.Slug,
		arg.Name,
		arg.SourceKey,
		arg.DataJson,
		arg.BodyText,
		arg.IsHomebrew,
		arg.ContentHash,
	)
	return err
}

const upsertCompendiumSource = `-- name: UpsertCompendiumSource :exec
INSERT INTO compendium_sources (source_key, path, hash, edition, license, attribution)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (source_key) DO UPDATE
SET path = excluded.path, hash = excluded.hash, edition = excluded.edition,
    license = excluded.license, attribution = excluded.attribution,
    last_imported = CURRENT_TIMESTAMP
`

type UpsertCompendiumSourceParams struct {
	SourceKey   string
	Path        string
	Hash        string
	Edition     string
	License     string
	Attribution string
}

func (q *Queries) UpsertCompendiumSource(ctx context.Context, arg UpsertCompendiumSourceParams) error {
	_, err := q.db.ExecContext(ctx, upsertCompendiumSource,
		arg.SourceKey,
		arg.Path,
		arg.Hash,
		arg.Edition,
		arg.License,
		arg.Attribution,
	)
	return err
}
